fn total_ordering(k: &Rc<Class>) -> Result<(), E> {
    const OPS: [&str;4] = ["__lt__","__le__","__gt__","__ge__"];
    let roots: Vec<&str> = OPS.iter().filter(|n| k.lookup(n).is_some_and(|v| !matches!(v, V::None))).copied().collect();
    if roots.is_empty() { return val_err(...) }
    let root = roots.iter().max().unwrap(); // lexicographic
    let rf = k.lookup(root).unwrap();
    for n in OPS where n != root && !roots.contains(n) {
       let r = rf.clone();
       let derived = func(n, move |a: Args| {
           let res = call(&r, Args::p(vec![a.p[0].clone(), a.p[1].clone()]))?;
           if matches!(res, V::NotImpl) { return Ok(res); }
           let t = truth(&res)?;
           Ok(V::Bool(match (root, n) {...}))
       });
       k.set(n, derived);
    }
    Ok(())
}
